package com.smritisathi.app.reminders;
import android.app.*;import android.content.*;import java.text.*;import java.util.*;
public class NotificationScheduler {public static void schedule(Context c,String id,String title,long when){AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent i=new Intent(c,ReminderReceiver.class);i.putExtra("reminderId",id);i.putExtra("title",title);PendingIntent p=PendingIntent.getBroadcast(c,id.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);if(when>System.currentTimeMillis())a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);}public static void cancel(Context c,String id){Intent i=new Intent(c,ReminderReceiver.class);PendingIntent p=PendingIntent.getBroadcast(c,id.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(p);}}
